return ['domain'=>'postvoyage-socialmedia-poster','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'de_DE','project-id-version'=>'PostVoyage - Free Social Media Post Distributor 0.1.0','pot-creation-date'=>'2026-10-18T19:38:57+00:00','po-revision-date'=>'YEAR-MO-DA HO:MI+ZONE','x-generator'=>'WP-CLI 2.12.0','messages'=>['PostVoyage - Free Social Media Post Distributor'=>'PostVoyage - Free Social Media Post Distributor','Shares your posts automatically on Mastodon, Bluesky, Telegram, Discord, Facebook, Threads, LinkedIn, X and any webhook. Free, with rules per category and templates with variables.'=>'Teilt deine Beiträge automatisch auf Mastodon, Bluesky, Telegram, Discord, Facebook, Threads, LinkedIn, X und per Webhook. Kostenlos, mit Regeln je Kategorie und Vorlagen mit Variablen.','Alexander Volland'=>'Alexander Volland','PostVoyage accounts'=>'PostVoyage-Konten','Add account'=>'Konto hinzufügen','Connect the profiles, pages and channels your posts should be shared to. Then decide in "Rules" which posts go where.'=>'Verbinde die Profile, Seiten und Kanäle, auf denen deine Beiträge erscheinen sollen. Unter „Regeln“ legst du dann fest, welche Beiträge wohin gehen.','No accounts connected yet.'=>'Noch keine Konten verbunden.','Connect your first account'=>'Erstes Konto verbinden','Name'=>'Name','Network'=>'Netzwerk','Status'=>'Status','Actions'=>'Aktionen','Network missing'=>'Netzwerk fehlt','Active'=>'Aktiv','Paused'=>'Pausiert','Edit'=>'Bearbeiten','Test connection'=>'Verbindung testen','Delete'=>'Löschen','Edit account'=>'Konto bearbeiten','Back to accounts'=>'Zurück zu den Konten','Your own name for this account, e.g. "Blog channel".'=>'Dein eigener Name für dieses Konto, z. B. „Blog-Kanal“.','Save and test connection'=>'Speichern und Verbindung testen','•••••••• saved – leave empty to keep'=>'•••••••• gespeichert – leer lassen zum Behalten','Account saved.'=>'Konto gespeichert.','Account deleted.'=>'Konto gelöscht.','Connection test "%1$s": %2$s'=>'Verbindungstest „%1$s“: %2$s','You are not allowed to do this.'=>'Dazu fehlt dir die Berechtigung.','Date'=>'Datum','Post'=>'Beitrag','Account'=>'Konto','Message'=>'Meldung','All'=>'Alle','Successful'=>'Erfolgreich','Errors'=>'Fehler','Nothing shared yet.'=>'Noch nichts geteilt.','Shared'=>'Geteilt','Error'=>'Fehler','View post'=>'Beitrag ansehen','Log'=>'Protokoll','Clear log'=>'Protokoll leeren','Log cleared.'=>'Protokoll geleert.','Accounts'=>'Konten','Rules'=>'Regeln','Settings'=>'Einstellungen','Sharing…'=>'Wird geteilt …','Done.'=>'Fertig.','Nothing was shared. Check the rules and accounts.'=>'Es wurde nichts geteilt. Prüfe Regeln und Konten.','Request failed.'=>'Anfrage fehlgeschlagen.','View'=>'Ansehen','Really delete?'=>'Wirklich löschen?','No active accounts.'=>'Keine aktiven Konten.','Share on publish'=>'Beim Veröffentlichen teilen','Custom text (optional)'=>'Eigener Text (optional)','Empty = rule template. Variables like {title} {url} {hashtags} work here too.'=>'Leer = Vorlage der Regel. Variablen wie {title} {url} {hashtags} funktionieren auch hier.','Sharing is queued and runs in the background shortly.'=>'Das Teilen ist eingeplant und läuft gleich im Hintergrund.','shared'=>'geteilt','failed – see log'=>'fehlgeschlagen – siehe Protokoll','Share now'=>'Jetzt teilen','None selected = accounts from the matching rules. Saves nothing – save your changes first.'=>'Keins ausgewählt = Konten aus den passenden Regeln. Speichert nichts – speichere Änderungen vorher.','Add rule'=>'Regel hinzufügen','A rule defines which posts (post type, category, language) are shared to which accounts and with which text. If several rules reach the same account, the topmost one wins.'=>'Eine Regel legt fest, welche Beiträge (Inhaltstyp, Kategorie, Sprache) mit welchem Text auf welchen Konten geteilt werden. Treffen mehrere Regeln dasselbe Konto, gewinnt die oberste.','Categories'=>'Kategorien','No rules yet. Without a rule nothing is shared automatically.'=>'Noch keine Regeln. Ohne Regel wird nichts automatisch geteilt.','Move up'=>'Nach oben','Move down'=>'Nach unten','Edit rule'=>'Regel bearbeiten','Back to rules'=>'Zurück zu den Regeln','Post types'=>'Inhaltstypen','None selected = all post types enabled in the settings.'=>'Keiner ausgewählt = alle in den Einstellungen aktivierten Inhaltstypen.','Include subcategories'=>'Unterkategorien einschließen','None selected = all categories.'=>'Keine ausgewählt = alle Kategorien.','Languages'=>'Sprachen','None selected = all languages. Tip: one rule per language lets you use a separate template and separate accounts per language.'=>'Keine ausgewählt = alle Sprachen. Tipp: Mit einer Regel pro Sprache kannst du je Sprache eigene Vorlagen und Konten nutzen.','None selected = all active accounts.'=>'Keins ausgewählt = alle aktiven Konten.','Text template'=>'Textvorlage','Texts are shortened automatically to the limit of each network; links are never cut.'=>'Texte werden automatisch auf das Limit des jeweiligen Netzwerks gekürzt; Links werden nie abgeschnitten.','Per network'=>'Pro Netzwerk','Own template for %s'=>'Eigene Vorlage für %s','Empty = use the template above'=>'Leer = Vorlage oben verwenden','Image'=>'Bild','Share the featured image (where the network supports it)'=>'Beitragsbild mitsenden (wo das Netzwerk es unterstützt)','Save rule'=>'Regel speichern','Insert:'=>'Einfügen:','Rule saved.'=>'Regel gespeichert.','Rule deleted.'=>'Regel gelöscht.','All active'=>'Alle aktiven','PostVoyage settings'=>'PostVoyage-Einstellungen','Publishing'=>'Veröffentlichen','PostVoyage only reacts to these post types.'=>'PostVoyage reagiert nur auf diese Inhaltstypen.','Default for new posts'=>'Standard für neue Beiträge','Share automatically on publish (can be changed per post)'=>'Beim Veröffentlichen automatisch teilen (pro Beitrag änderbar)','Delay'=>'Verzögerung','seconds'=>'Sekunden','Sharing runs in the background after this delay. At least 30 seconds are recommended so that settings in the editor are saved and caches are warmed up.'=>'Das Teilen läuft nach dieser Verzögerung im Hintergrund. Empfohlen sind mindestens 30 Sekunden, damit Einstellungen im Editor gespeichert und Caches aufgewärmt sind.','Tracking'=>'Tracking','UTM parameters'=>'UTM-Parameter','Add UTM parameters to {url}'=>'UTM-Parameter an {url} anhängen','{network} is replaced with the network, e.g. "mastodon".'=>'{network} wird durch das Netzwerk ersetzt, z. B. „mastodon“.','Maintenance'=>'Wartung','Keep log for'=>'Protokoll aufbewahren für','days'=>'Tage','Uninstall'=>'Deinstallation','Delete all PostVoyage data (accounts, rules, log) when the plugin is deleted'=>'Alle PostVoyage-Daten (Konten, Regeln, Protokoll) beim Löschen des Plugins entfernen','System'=>'System','Background processing'=>'Hintergrundverarbeitung','Action Scheduler'=>'Action Scheduler','Yes – make sure a server cron job calls wp-cron.php regularly.'=>'Ja – stelle sicher, dass ein Server-Cronjob wp-cron.php regelmäßig aufruft.','No'=>'Nein','Multilingual plugin'=>'Mehrsprachigkeits-Plugin','None detected (Polylang and WPML are supported)'=>'Keins erkannt (Polylang und WPML werden unterstützt)','Version'=>'Version','Post title'=>'Beitragstitel','Excerpt (or the beginning of the content)'=>'Textauszug (oder der Anfang des Inhalts)','Full content as plain text'=>'Gesamter Inhalt als reiner Text','Link to the post (with UTM parameters if enabled)'=>'Link zum Beitrag (mit UTM-Parametern, falls aktiviert)','Link to the post without UTM parameters'=>'Link zum Beitrag ohne UTM-Parameter','WordPress short link (?p=123)'=>'WordPress-Kurzlink (?p=123)','Tags as hashtags'=>'Schlagwörter als Hashtags','Categories as hashtags'=>'Kategorien als Hashtags','Tags, comma separated'=>'Schlagwörter, durch Komma getrennt','Categories, comma separated'=>'Kategorien, durch Komma getrennt','Author name'=>'Name des Autors','Publish date'=>'Veröffentlichungsdatum','Site title'=>'Titel der Website','Site address'=>'Adresse der Website','Language code of the post'=>'Sprachcode des Beitrags','Name of the network'=>'Name des Netzwerks','Value of the custom field "field"'=>'Wert des benutzerdefinierten Feldes „field“','Network not available.'=>'Netzwerk nicht verfügbar.','In Bluesky open Settings → Privacy and security → App passwords and create a new app password. Never use your main password.'=>'Öffne in Bluesky Einstellungen → Privatsphäre und Sicherheit → App-Passwörter und erstelle ein neues App-Passwort. Verwende nie dein Hauptpasswort.','Handle'=>'Handle','e.g. name.bsky.social'=>'z. B. name.bsky.social','App password'=>'App-Passwort','PDS server'=>'PDS-Server','Only change this if you host your own PDS.'=>'Nur ändern, wenn du einen eigenen PDS betreibst.','Connected as @%s'=>'Verbunden als @%s','Login failed.'=>'Anmeldung fehlgeschlagen.','Image upload failed.'=>'Bild-Upload fehlgeschlagen.','In Discord open the channel settings → Integrations → Webhooks → New webhook, then copy the webhook URL.'=>'Öffne in Discord die Kanaleinstellungen → Integrationen → Webhooks → Neuer Webhook und kopiere die Webhook-URL.','Webhook URL'=>'Webhook-URL','Display name'=>'Anzeigename','Optional, overrides the webhook name.'=>'Optional, überschreibt den Namen des Webhooks.','Show as card (embed) with title and image'=>'Als Karte (Embed) mit Titel und Bild anzeigen','Webhook "%s" found'=>'Webhook „%s“ gefunden','This is not a Discord webhook URL.'=>'Das ist keine Discord-Webhook-URL.','Create an app at developers.facebook.com, generate a long-lived page access token with the permissions pages_manage_posts and pages_read_engagement (e.g. with the Graph API Explorer) and enter the numeric page ID.'=>'Lege auf developers.facebook.com eine App an, erzeuge ein langlebiges Seiten-Zugriffstoken mit den Berechtigungen pages_manage_posts und pages_read_engagement (z. B. mit dem Graph API Explorer) und trage die numerische Seiten-ID ein.','Page ID'=>'Seiten-ID','Page access token'=>'Seiten-Zugriffstoken','Graph API version'=>'Graph-API-Version','Leave empty for the default (%s).'=>'Leer lassen für den Standard (%s).','Connected to page "%s"'=>'Verbunden mit Seite „%s“','Create an app at linkedin.com/developers with the products "Share on LinkedIn" and "Sign In with LinkedIn using OpenID Connect" and generate an access token (scopes: openid, profile, w_member_social) with the OAuth token generator. Tokens are valid for 60 days. Leave the author empty to post as yourself; company pages need urn:li:organization:ID and the w_organization_social scope.'=>'Lege auf linkedin.com/developers eine App mit den Produkten „Share on LinkedIn“ und „Sign In with LinkedIn using OpenID Connect“ an und erzeuge mit dem OAuth-Token-Generator ein Zugriffstoken (Scopes: openid, profile, w_member_social). Tokens gelten 60 Tage. Lass den Autor leer, um als du selbst zu posten; für Unternehmensseiten brauchst du urn:li:organization:ID und den Scope w_organization_social.','Access token'=>'Zugriffstoken','Author'=>'Autor','Optional: urn:li:person:… or urn:li:organization:…'=>'Optional: urn:li:person:… oder urn:li:organization:…','API version'=>'API-Version','Optional, format YYYYMM. Empty = automatically a recent version.'=>'Optional, Format JJJJMM. Leer = automatisch eine aktuelle Version.','Connected as %1$s (%2$s)'=>'Verbunden als %1$s (%2$s)','Could not determine the LinkedIn author. Please enter it in the account settings.'=>'Der LinkedIn-Autor konnte nicht ermittelt werden. Bitte trage ihn in den Kontoeinstellungen ein.','On your Mastodon server open Preferences → Development → New application. Scopes "write:statuses" and "write:media" are enough. Copy "Your access token".'=>'Öffne auf deinem Mastodon-Server Einstellungen → Entwicklung → Neue Anwendung. Die Scopes „write:statuses“ und „write:media“ reichen. Kopiere „Dein Zugriffstoken“.','Server URL'=>'Server-URL','e.g. https://mastodon.social'=>'z. B. https://mastodon.social','Visibility'=>'Sichtbarkeit','Public'=>'Öffentlich','Unlisted'=>'Nicht gelistet','Followers only'=>'Nur Follower','Character limit'=>'Zeichenlimit','Some servers allow more than 500.'=>'Manche Server erlauben mehr als 500.','Upload featured image'=>'Beitragsbild hochladen','Off: Mastodon shows a link preview card instead.'=>'Aus: Mastodon zeigt stattdessen eine Link-Vorschau.','Create a bot with @BotFather and copy the token. Add the bot as administrator to your channel. Chat ID: @channelname for public channels, otherwise the numeric ID (e.g. -100…).'=>'Erstelle mit @BotFather einen Bot und kopiere das Token. Füge den Bot als Administrator zu deinem Kanal hinzu. Chat-ID: @kanalname bei öffentlichen Kanälen, sonst die numerische ID (z. B. -100…).','Bot token'=>'Bot-Token','Chat ID'=>'Chat-ID','e.g. @mychannel or -1001234567890'=>'z. B. @meinkanal oder -1001234567890','Send featured image'=>'Beitragsbild senden','With an image the text is limited to 1024 characters.'=>'Mit Bild ist der Text auf 1024 Zeichen begrenzt.','Disable link preview'=>'Link-Vorschau deaktivieren','Send silently (no notification sound)'=>'Still senden (ohne Benachrichtigungston)','Bot @%1$s can reach "%2$s"'=>'Bot @%1$s erreicht „%2$s“','Create a Meta app with the "Threads API" use case and the permissions threads_basic and threads_content_publish, then generate a long-lived access token. PostVoyage refreshes it weekly so it does not expire.'=>'Lege eine Meta-App mit dem Anwendungsfall „Threads API“ und den Berechtigungen threads_basic und threads_content_publish an und erzeuge ein langlebiges Zugriffstoken. PostVoyage erneuert es wöchentlich, damit es nicht abläuft.','User ID'=>'Benutzer-ID','Optional, "me" is used by default.'=>'Optional, standardmäßig wird „me“ verwendet.','Threads did not return a container ID.'=>'Threads hat keine Container-ID zurückgegeben.','Sends a JSON POST request with text, link, title, image URL, tags and language. With a secret, the header X-PostVoyage-Signature contains "sha256=" plus the HMAC of the body.'=>'Sendet einen JSON-POST-Request mit Text, Link, Titel, Bild-URL, Schlagwörtern und Sprache. Mit Secret enthält der Header X-PostVoyage-Signature „sha256=“ plus den HMAC des Bodys.','Signing secret'=>'Signatur-Secret','Optional.'=>'Optional.','Optional, empty = unlimited.'=>'Optional, leer = unbegrenzt.','Webhook answered with HTTP %d'=>'Webhook antwortete mit HTTP %d','Create a project and app at developer.x.com, set the app permissions to "Read and write" and then generate API key/secret and access token/secret. Note: how many posts the X API allows depends on your API plan.'=>'Lege auf developer.x.com ein Projekt mit App an, setze die App-Berechtigungen auf „Read and write“ und erzeuge danach API-Key/-Secret und Access-Token/-Secret. Hinweis: Wie viele Posts die X-API erlaubt, hängt von deinem API-Tarif ab.','API key'=>'API-Key','API key secret'=>'API-Key-Secret','Access token secret'=>'Access-Token-Secret','When a post is published, this site sends the post title, excerpt, link and featured image to the social networks configured by the site owner (for example Mastodon, Bluesky, Telegram, Discord, Facebook, Threads, LinkedIn or X). No data about visitors is transmitted.'=>'Wenn ein Beitrag veröffentlicht wird, sendet diese Website Titel, Textauszug, Link und Beitragsbild an die vom Betreiber eingerichteten sozialen Netzwerke (zum Beispiel Mastodon, Bluesky, Telegram, Discord, Facebook, Threads, LinkedIn oder X). Daten über Besucher werden nicht übertragen.','Unknown network.'=>'Unbekanntes Netzwerk.','Please fill in "%s".'=>'Bitte „%s“ ausfüllen.','All posts'=>'Alle Beiträge','Unnamed rule'=>'Unbenannte Regel']];